constructor(config) {
    this.config = config;
    this.scanimage = new Scanimage(config);
  }

_format(value) {
    if (['boolean', 'number'].includes(typeof value)) {
      return `${value}`;
    } else if ('string' === typeof value) {
      if (value.includes('\'')) {
        throw Error('Argument must not contain single quote "\'"');
      } else if (/^[0-9a-z-=/~.:]+$/i.test(value)) {
        return `${value}`;
      }
      return `'${value}'`;
    }
    throw Error(`Invalid argument type: '${typeof value}'`);
  }

function commandFor(version, request) {
  const temp = scanimageCommand.scanimage._version;
  scanimageCommand.scanimage._version = version;
  const command = scanimageCommand.scan(request);
  scanimageCommand.scanimage._version = temp;
  return command;
}

constructor(config) {
    this.config = config;
  }

arg(...values) {
    this.args.push(...values
      .filter(s => s !== undefined)
      .map(this._format));
    return this;
  }

get version() {
    if (this._version === undefined) {
      const result = Process.executeSync(`${this.config.scanimage} -V`);
      this._version = /.*backend version (.*)/.exec(result)[1];
    }
    return this._version;
  }

filename(page) {
    const number = `000${page}`.slice(-4);
    return `${this.config.tempDirectory}/${Constants.TEMP_FILESTEM}-0-${number}.tif`;
  }

constructor(cmd) {
    this.cmd = cmd;
    this.args = [];
  }

devices() {
    return new CommandBuilder(this.config.scanimage)
      .arg('-L')
      .build();
  }

_format(value) {
    if (typeof value === 'string') {
      if (value.includes('\'')) {
        throw Error('Argument must not contain single quote "\'"');
      } else if (['$', ' ', '#', '\\', ';'].some(c => value.includes(c))) {
        return `'${value}'`;
      }
    }
    return `${value}`;
  }

features(deviceId) {
    return new CommandBuilder(this.config.scanimage)
      .arg('-d', deviceId)
      .arg('-A')
      .build();
  }

build(ignoreStderr) {
    log.trace('build()', this);
    let cmd = this.cmd;
    for (const arg of this.args) {
      cmd += ' ' + arg;
    }
    if (ignoreStderr) {
      cmd += ' 2>/dev/null';
    }
    log.trace('build()', cmd);
    return cmd;
  }

get supportsOutputFlag() {
    return semver.satisfies(this.version, '>=1.0.28');
  }

redirect(operator) {
    if (typeof operator !== 'string' || !/^[&<>|]+$/.test(operator)) {
      throw Error(`Invalid argument: '${operator}'`);
    }
    this.args.push(operator);
    return this;
  }

