async function changeCurrentSlide(meetingId, podId, presentationId, slideId) {
  check(meetingId, String);
  check(presentationId, String);
  check(slideId, String);
  check(podId, String);

  const oldCurrent = {
    selector: {
      meetingId,
      podId,
      presentationId,
      current: true,
    },
    modifier: {
      $set: { current: false },
    },
    callback: (err) => {
      if (err) {
        Logger.error(`Unsetting the current slide: ${err}`);
        return;
      }

      Logger.info('Unsetted the current slide');
    },
  };

  const newCurrent = {
    selector: {
      meetingId,
      podId,
      presentationId,
      id: slideId,
    },
    modifier: {
      $set: { current: true },
    },
    callback: (err) => {
      if (err) {
        Logger.error(`Setting as current slide id=${slideId}: ${err}`);
        return;
      }

      Logger.info(`Setted as current slide id=${slideId}`);
    },
  };

  const oldSlide = await Slides.findOneAsync(oldCurrent.selector);
  const newSlide = await Slides.findOneAsync(newCurrent.selector);

  // if the oldCurrent and newCurrent have the same ids
  if (oldSlide && newSlide && (oldSlide._id === newSlide._id)) {
    return;
  }

  if (newSlide) {
    await Slides.updateAsync(newSlide._id, newCurrent.modifier, newCurrent.callback);
  }

  if (oldSlide) {
    await Slides.updateAsync(oldSlide._id, oldCurrent.modifier, oldCurrent.callback);
  }
}

async moderatorAsPresenter(testName) {
    try {
      const maxFailRate = c.JOIN_AS_MODERATOR_TEST_ROUNDS * c.MAX_JOIN_AS_MODERATOR_FAIL_RATE;
      let failureCount = 0;
      for (let i = 1; i <= c.JOIN_AS_MODERATOR_TEST_ROUNDS; i++) {
        await this.modPage.init(true, true, testName, `Moderator-${i}`);
        await this.modPage.waitForSelector(e.userAvatar);
        const hasPresenterClass = await this.modPage.page.evaluate(util.checkIncludeClass, e.userAvatar, e.presenterClassName);
        await this.modPage.waitAndClick(e.actions);
        const canStartPoll = await this.modPage.hasElement(e.polling);
        if (!hasPresenterClass || !canStartPoll) {
          failureCount++;
          await this.modPage.screenshot(testName, `loop-${i}-failure-${testName}`);
        }
        await this.modPage.close();
        await this.modPage.logger(`Loop ${i} of ${c.JOIN_AS_MODERATOR_TEST_ROUNDS} completed`);
        if (failureCount > maxFailRate) return false;
      }
      return true;
    } catch (err) {
      await this.modPage.logger(err);
      return false;
    }
  }

async function addBulkGroupChatMsgs(msgs) {
