    name: user.name,
    isTypingTo: chatId,
    role: user.role,
    time: (new Date()),
  };

  const typingUser = await UsersTyping.findOneAsync(selector, {
    fields: {
      time: 1,
    },
  });

  if (typingUser) {
    if (modifier.time - typingUser.time <= TYPING_TIMEOUT - 100) return;
