  try {
    const { numberAffected } = await UsersTyping.upsertAsync(selector, modifier);

    if (numberAffected) {
      Logger.debug('Typing indicator update', { userId, chatId });
      Meteor.setTimeout(() => {
        stopTyping(meetingId, userId);
      }, TYPING_TIMEOUT);
