async function users() {
  const tokenValidation = await AuthTokenValidation
    .findOneAsync({ connectionId: this.connection.id });

  if (!tokenValidation || tokenValidation.validationStatus !== ValidationStates.VALIDATED) {
    Logger.warn(`Publishing Users was requested by unauth connection ${this.connection.id}`);
    return Users.find({ meetingId: '' });
  }

  if (!this.userId) {
    return Users.find({ meetingId: '' });
  }
  const { meetingId, userId } = tokenValidation;

  Logger.debug(`Publishing Users for ${meetingId} ${userId}`);

  const selector = {
    $or: [
      { meetingId },
    ],
    intId: { $exists: true },
    left: false,
  };

  const User = await Users.findOneAsync({ userId, meetingId }, { fields: { role: 1 } });
  if (!!User && User.role === ROLE_MODERATOR) {
    selector.$or.push({
      'breakoutProps.isBreakoutUser': true,
      'breakoutProps.parentId': meetingId,
    });
    // Monitor this publication and stop it when user is not a moderator anymore
    const comparisonFunc = async () => {
      const user = await Users.findOneAsync({ userId, meetingId },
        { fields: { role: 1, userId: 1 } });
      const condition = user.role === ROLE_MODERATOR;
      if (!condition) {
        Logger.info(`conditions aren't filled anymore in publication ${this._name}: 
        user.role === ROLE_MODERATOR :${condition}, user.role: ${user.role} ROLE_MODERATOR: ${ROLE_MODERATOR}`);
      }

      return condition;
    };
    publicationSafeGuard(comparisonFunc, this);
  }

  const options = {
    fields: {
      authToken: false,
    },
  };

  Logger.debug('Publishing Users', { meetingId, userId });

  return Users.find(selector, options);
}

function handleTimeRemainingUpdate({ body }, meetingId) {
  check(meetingId, String);

  check(body, {
    timeLeftInSec: Number,
    timeUpdatedInMinutes: Number,
  });
  const { timeLeftInSec, timeUpdatedInMinutes } = body;

  const selector = {
    meetingId,
  };

  const modifier = {
    $set: {
      timeRemaining: timeLeftInSec,
    },
  };

  try {
    MeetingTimeRemaining.upsert(selector, modifier);
  } catch (err) {
    Logger.error(`Changing recording time: ${err}`);
  }

  if (timeUpdatedInMinutes > 0) {
    const Meeting = Meetings.findOne({ meetingId });

    if (Meeting.meetingProp.isBreakout) {
      const CHAT_CONFIG = Meteor.settings.public.chat;
      const PUBLIC_GROUP_CHAT_ID = CHAT_CONFIG.public_group_id;
      const PUBLIC_CHAT_SYSTEM_ID = CHAT_CONFIG.system_userid;
      const PUBLIC_CHAT_INFO = CHAT_CONFIG.system_messages_keys.chat_info;
      const SYSTEM_CHAT_TYPE = CHAT_CONFIG.type_system;

      const messageValues = {
        0: timeUpdatedInMinutes,
      };

      const payload = {
        id: `${SYSTEM_CHAT_TYPE}-${PUBLIC_CHAT_INFO}`,
        timestamp: Date.now(),
        correlationId: `${PUBLIC_CHAT_SYSTEM_ID}-${Date.now()}`,
        sender: {
          id: PUBLIC_CHAT_SYSTEM_ID,
          name: '',
        },
        message: 'breakoutDurationUpdated',
        messageValues,
      };

      addSystemMsg(meetingId, PUBLIC_GROUP_CHAT_ID, payload);
    }
  }
}

