delete(name, when) {
        if (when) {
            const h = {};

            if (when instanceof Date) {
                h['X-Delete-At'] = +when / 1000;
            } else if (typeof when === 'number' || when instanceof Number) {
                h['X-Delete-After'] = when;
            } else {
                throw new Error('expected when to be a number of seconds or a date');
            }

            return this.authenticator.authenticate().then(auth => {
                return requestp({
                    method: 'POST',
                    uri: `${auth.url + this.urlSuffix}/${name}`,
                    headers: this.headers(null, h, auth.token)
                });
            });

        } else {
            return SwiftEntity.prototype.delete.call(this, name);
        }
    }

list(extra, query) {
        const querystring = query ? '?' + queryString.stringify(query) : '';
        return this.authenticator.authenticate().then(auth => { return axios({
            url: auth.url + this.urlSuffix + querystring,
            headers: this.headers(null, extra, auth.token),
            json: true
        }).then((response) => response.data); });
    }

headers(meta, extra, token) {
        const headers = Object.assign({
            'accept': 'application/json',
            'x-auth-token': token
        }, extra);

        if (meta != null) {
            for (const k in meta) {
                if (meta.hasOwnProperty(k)) {
                    headers[`X-${this.childName}-Meta-${k}`] = meta[k];
                }
            }
        }

        return headers;
    }

