constructor (readOnly) {
        if (!this.panel) {
            this.readOnly = readOnly;

            this.viewEditPanel = new Ext.Panel({
                region: 'center',
                width: '75%',
                autoScroll: true,
                padding: 10
            });

            this.viewTreeStore = new Ext.data.TreeStore({
                autoLoad: true,
                proxy: {
                    type: 'ajax',
                    url: this.routePrefix + '/get-tree',
                    reader: {
                        type: 'json'
                    }
                },
                listeners: {
                    datachanged: function(treestore){
                        let availableViewsStoreData = [];
                        const viewData = treestore.getRoot().serialize();
                        if(viewData.children) {
                            availableViewsStoreData = viewData.children.map(function(view){
                                return {id: view.id, name: view.config.name + ' (type: ' + view.config.treetype + ', folder: ' + view.config.rootfolder +')'};
                            });
                        }
                        const availableViewsStore = Ext.getStore('availableViewsStore');
                        availableViewsStore.setData(availableViewsStoreData);
                    }.bind(this),
                },
            });

            let toolbarButtons = [];
            let bottomButtons = [
                "->",
                new Ext.Button({
                    text: t("reload"),
                    iconCls: "pimcore_icon_reload",
                    handler: function(){
                        Ext.MessageBox.show({
                            title:t('plugin_pimcore_perspectiveeditor_are_you_sure'),
                            msg: t('plugin_pimcore_perspectiveeditor_confirm_reload'),
                            buttons: Ext.Msg.OKCANCEL ,
                            icon: Ext.MessageBox.INFO ,
                            fn: function (button) {
                                if (button === 'ok') {
                                    this.viewTreeStore.reload();
                                    this.viewEditPanel.removeAll();
                                    this.setDirty(false);
                                }
                            }.bind(this)
                        });
                    }.bind(this)
                })
            ];

            if(!readOnly) {
                toolbarButtons.push(new Ext.Button({
                    text: t('plugin_pimcore_perspectiveeditor_add_view'),
                    iconCls: "pimcore_icon_plus",
                    disabled: !pimcore.settings['custom-views-writeable'],
                    handler: function () {
                        Ext.MessageBox.prompt(t('plugin_pimcore_perspectiveeditor_new_view'), t('plugin_pimcore_perspectiveeditor_new_view'), function (button, value) {
                            value = pimcore.helpers.sanitizeString(value);

                            if (button === 'ok' && value.length > 0) {
                                const record = this.viewTreeStore.getRoot().appendChild({
                                    id: pimcore.bundle.perspectiveeditor.PerspectiveViewHelper.generateUuid(),
                                    text: value,
                                    type: 'view',
                                    icon: '/bundles/pimcoreadmin/img/flat-color-icons/view_details.svg',
                                    leaf: true,
                                    cls: 'plugin_pimcore_perspective_editor_custom_view_tree_item',
                                    writeable: true,
                                    config: {
                                        name: value,
                                        treetype: 'document',
                                        position: 'left',
                                        rootfolder: '/',
                                        showroot: false,
                                        sort: 0,
                                    }
                                });
                                this.buildViewEditorPanel(record);
                                this.setDirty(true);

                                pimcore.bundle.perspectiveeditor.PerspectiveViewHelper.reloadTreeNode(this.viewTreeStore.getRoot().lastChild);
                            }
                        }.bind(this))
                    }.bind(this)
                }));

                bottomButtons.push(new Ext.Button({
                    text: t('save'),
                    iconCls: "pimcore_icon_save",
                    disabled: !pimcore.settings['custom-views-writeable'],
                    handler: function(){
                        Ext.Ajax.request({
                            url: this.routePrefix + '/update',
                            params: {
                                data: Ext.JSON.encode(this.viewTreeStore.getRoot().serialize()),
                                deletedRecords: Ext.JSON.encode(this.deletedRecords)
                            },
                            method: 'POST',
                            success: function(response){
                                const responseObject = Ext.decode(response.responseText);
                                if(responseObject.success){
                                    pimcore.helpers.showNotification(t("success"), t("saved_successfully"), "success");
                                    this.setDirty(false);
                                    this.deletedRecords = [];
                                }
                                else{
                                    pimcore.helpers.showNotification(t("error"), responseObject.error, "error")
                                }
                            }.bind(this)
                        });
                    }.bind(this)
                }));
            }

            this.panel = new Ext.Panel({
                title: t("plugin_pimcore_perspectiveeditor_view_editor"),
                iconCls: "pimcore_icon_custom_views",
                border: false,
                layout: "border",
                items: [
                    new Ext.tree.Panel({
                        region: "west",
                        autoScroll: true,
                        animate: false,
                        containerScroll: true,
                        width: '25%',
                        split: true,
                        store: this.viewTreeStore,
                        rootVisible: false,
                        listeners: {
                            itemclick: function(tree, record){
                                this.buildViewEditorPanel(record);
                            }.bind(this),
                            itemcontextmenu: function (tree, record, item, index, e, eOpts ) {

                                e.stopEvent();
                                if(!readOnly) {
                                    var menu = new Ext.menu.Menu({
                                        items: [
                                            Ext.menu.Item({
                                                text: t('delete'),
                                                iconCls: "pimcore_icon_delete",
                                                disabled: !record.data["writeable"],
                                                handler: function(){
                                                    if(record.data['writeable']) {
                                                        Ext.MessageBox.show({
                                                            title: t('plugin_pimcore_perspectiveeditor_are_you_sure'),
                                                            msg: t('plugin_pimcore_perspectiveeditor_all_content_will_be_lost'),
                                                            buttons: Ext.Msg.OKCANCEL,
                                                            icon: Ext.MessageBox.INFO,
                                                            fn: function (button) {
                                                                if (button === 'ok') {
                                                                    if (record.id === this.activeRecordId) {
                                                                        this.viewEditPanel.removeAll();
                                                                    }
                                                                    this.deletedRecords.push(record.data.id);
                                                                    record.parentNode.removeChild(record);
                                                                    this.setDirty(true);
                                                                }
                                                            }.bind(this)
                                                        });
                                                    }
                                                    else {
                                                        pimcore.helpers.showNotification(t("info"), t("config_not_writeable"), "info");
                                                    }
                                                }.bind(this)
                                            })
                                        ]
                                    });
                                    menu.showAt(e.pageX, e.pageY);
                                }
                            }.bind(this)
                        },
                        tbar: {
                            cls: 'pimcore_toolbar_border_bottom',
                            items: toolbarButtons,
                        },
                    }),
                    this.viewEditPanel
                ],
                buttons: bottomButtons
            });
        }

        return this.panel;
    }

createToolbarFormPanel (record){
        record.data.config = Object.assign({}, record.data.config);
        var config = record.data.config;
        let additionalStructures = pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadStructureForPermissions('toolbar');
        var structure = {
            file: pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadPermissions('toolbar', 'file'),
            marketing: pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadPermissions('toolbar', 'marketing'),
            extras: pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadPermissions('toolbar', 'extras'),
            settings: pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadPermissions('toolbar', 'settings'),
            search: pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadPermissions('toolbar', 'search'),
        };
        Object.entries(additionalStructures).forEach((kvp) => {
            let key = kvp[0];
            structure[key] = pimcore.bundle.perspectiveeditor.MenuItemPermissionHelper.loadPermissions('toolbar', key);
        });

        pimcore.bundle.perspectiveeditor.PerspectiveViewHelper.checkAndCreateDataStructure(config, structure);

        let fieldSetItems = [];
        Object.entries(config).forEach((kvp) => {
            let menuItems = [];
            let key = kvp[0];
            let value = kvp[1];
            pimcore.bundle.perspectiveeditor.PerspectiveViewHelper.generateCheckboxesForStructure(value, menuItems, this.setDirty.bind(this, true), 'plugin_pimcore_perspectiveeditor_menu_' + key);

            fieldSetItems.push(new Ext.form.FieldSet({
                title: t('plugin_pimcore_perspectiveeditor_' + key),
                collapsible: true,
                items: menuItems
            }));
        });

        fieldSetItems.sort((a,b) => {
            return a.title.localeCompare(b.title);
        })

        return new Ext.Panel({
            title: t('plugin_pimcore_perspectiveeditor_toolbar_access'),
            iconCls: 'pimcore_icon_support',
            disabled: !record.data["writeable"],
            items: [
                new Ext.Panel({
                    width: '50%',
                    padding: '10',
                    autoscroll: true,
                    items: fieldSetItems
                })
            ]
        });
    }

