    const that = this
    $(this._select).each(function (idx) {
      const s = $(this)
        .select2({
          placeholder: $L('选择 %d 级分类', idx + 1),
          allowClear: false,
        })
        .on('change', () => {
          const p = $(s).val()
          if (p) {
